            confluence_sync_markdown_directory: function() { return JSON.stringify({ syncedPages: [] }); },
            jira_post_comment: function(a) { jiraComments.push(a); },
            ado_add_work_item_comment: function(a) { adoComments.push(a); },
            file_write: function() {}
