// ── File helpers ─────────────────────────────────────────────────────────────

function resolveAgentPath(path) {
    // When running from agents/ directory, paths like ./agents/... or agents/... need translation
    if (path.indexOf('./agents/') === 0) {
        return path.substring('./agents/'.length);
    }
    if (path.indexOf('agents/') === 0) {
        return path.substring('agents/'.length);
    }
