    if (cliPromptsByTracker && cliPromptsByTracker[effectiveTracker]) {
        var trackerPrompts = cliPromptsByTracker[effectiveTracker];
        if (trackerPrompts && Array.isArray(trackerPrompts) && trackerPrompts.length > 0) {
