var AGENT_JSON_PATTERN = /^[a-zA-Z0-9_]+\.json$/;
var ACTION_PARAMS = ['preJSAction', 'preCliJSAction', 'postCliJSAction', 'postJSAction', 'timerJSAction'];
var EXCLUDED = {
    'sm.json': true,
    'sm_merge.json': true,
