function selectRuleQuery(rule, trackerProvider) {
    if (!rule) return null;
    var map = rule.jqlByTracker;
    var provider = String(trackerProvider || '').toLowerCase();
    if (map && typeof map === 'object' && provider && typeof map[provider] === 'string' && map[provider]) {
        return map[provider];
    }
    return rule.jql;
}

