/**
 * Pre-CLI Content Output Setup — shared pre-action for content-generating
 * agents (story_description, story_acceptance_criteria, …).
 *
 * Chains:
 *   1. fetchQuestionsToInput.js — fetch question subtasks into input folder
 *   2. fetchConfluenceOutputContext.js — when contentOutput targets Confluence,
 *      snapshot the existing page + inline comments into the input folder
 *      (no-op otherwise, so behavior without contentOutput is unchanged)
 */

var fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
var fetchConfluenceOutputContext = require('./fetchConfluenceOutputContext.js');

function action(params) {
    try {
        var jobParams = params.jobParams || params;
        var actualParams = params.inputFolderPath ? params : jobParams;

        fetchQuestionsToInput.action(actualParams);

        try {
            fetchConfluenceOutputContext.action(actualParams);
        } catch (e) {
            console.warn('fetchConfluenceOutputContext failed (non-fatal):', e);
        }
    } catch (error) {
        console.error('Error in preCliContentOutputSetup:', error);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

/**
 * Content Output — shared library for routing agent-generated content
 * (solution / description / acceptance criteria) to a Jira field and/or a
 * Confluence page, with Confluence inline-comment support.
 *
 * Used by:
 *   - js/writeContentOutput.js            (post-action for story_description,
 *                                          story_acceptance_criteria, …)
 *   - js/fetchConfluenceOutputContext.js  (pre-action: snapshot existing page
 *                                          + inline comments into input/)
 *   - js/writeSolutionAndDiagrams.js      (story_solution; Confluence target)
 *
 * Configuration (customParams.contentOutput in the agent JSON, or
 * projectConfig.contentOutput in .dmtools/config.js; customParams win):
 *
 *   contentOutput: {
 *     target: 'jira_field',     // 'jira_field' (default) | 'confluence' | 'both'
 *     field: 'Description',     // tracker field for jira_field target
 *     operationType: 'replace', // 'replace' (default) | 'append'
 *     updateTrackerField: true, // for confluence/both: write a link (or the
 *                               // content) into the tracker field too
 *     space: '',                // Confluence space key (required for confluence target)
 *     parentPageId: '',         // parent page the ticket page nests under
 *     pageTitleSuffix: '',      // e.g. 'Solution Design' → page title
 *                               // '{ticketKey} {summary} — Solution Design'
 *     deleteOrphans: false,     // passed to confluence_sync_markdown_directory
 *     includeInlineComments: true
 *   }
 */

var configLoader = null;
try { configLoader = require('../configLoader.js'); } catch (e) { /* unit tests inject their own */ }

// gh-823: load-time require — a deferred (in-function) require resolves
// against the pack's js/ root only at runtime ("Failed to require module:
// ./trackers.js"); load-time requires resolve file-relative and dmtools
// compile discovers them for the pack closure.
var trackersModule = require('./trackers.js');

var DEFAULT_REPLIES_FILE = 'outputs/confluence_replies.json';
var COMMENTS_BASE_NAME = 'confluence_output_comments';

// ── Config resolution ────────────────────────────────────────────────────────

function mergeObjects(base, override) {
    var result = {};
    var key;
    for (key in (base || {})) {
        if (Object.prototype.hasOwnProperty.call(base, key)) result[key] = base[key];
    }
    for (key in (override || {})) {
        // undefined means "not set" — it must not shadow a base/default value
        if (Object.prototype.hasOwnProperty.call(override, key) && override[key] !== undefined) {
            result[key] = override[key];
        }
    }
    return result;
}

function resolveConfig(params, defaults) {
    var customParams = (params && params.customParams) ||
        (params && params.jobParams && params.jobParams.customParams) || {};
    var fromCustom = customParams.contentOutput || {};

    var fromProject = {};
    try {
        // gh-823: the loader holder is resolved at LOAD TIME (the top-level
        // try above) — no deferred fallback require here. A require executed
        // after module init resolves against the pack's js/ root only, so
        // the old `configLoader || require('../configLoader.js')` fallback
        // could only ever look at <packRoot>/configLoader.js, outside js/ —
        // the exact gh-823 miss shape. When the load-time require failed
        // (unit tests inject their own), best-effort stays fail-open.
        var loader = configLoader;
        var projectConfig = loader.loadProjectConfig((params && params.jobParams) || params || {});
        fromProject = (projectConfig && projectConfig.contentOutput) || {};
    } catch (e) {
        // config loading is best-effort here; callers usually pass jobParams
    }

    // Priority (low → high): built-in defaults < caller defaults < project config < customParams
    var cfg = {
        target: 'jira_field',
        operationType: 'replace',
        updateTrackerField: true,
        space: '',
        parentPageId: '',
        pageTitleSuffix: '',
        deleteOrphans: false,
        includeInlineComments: true
    };
    cfg = mergeObjects(cfg, defaults);
    cfg = mergeObjects(cfg, fromProject);
    cfg = mergeObjects(cfg, fromCustom);
    return cfg;
}

function isConfluenceTarget(cfg) {
    return cfg.target === 'confluence' || cfg.target === 'both';
}

function isJiraFieldTarget(cfg) {
    return cfg.target === 'jira_field' || cfg.target === 'both';
}

// ── Jira field write ─────────────────────────────────────────────────────────

/**
 * Write content to a tracker field. Supports replace (default) and append
 * modes. Append reads the current field value; ADF values (Jira v3) cannot be
 * merged with wiki markup and fall back to replace.
 */
function writeToTrackerField(ticketKey, field, content, operationType, tracker) {
    var valueToWrite = content;
    if (!tracker) tracker = trackersModule.createTracker(null, {});
    if (operationType === 'append') {
        var existing = '';
        try {
            var freshTicket = tracker.getIssue(ticketKey, [field]);
            var freshFields = (freshTicket && freshTicket.fields) ? freshTicket.fields : freshTicket;
            var rawValue = freshFields ? freshFields[field] : null;
            if (rawValue && typeof rawValue === 'object') {
                console.warn('Existing value of "' + field + '" is in ADF format. Cannot merge — falling back to replace.');
                rawValue = '';
            }
            existing = (rawValue || '').toString().trim();
        } catch (e) {
            console.warn('Could not read existing value of "' + field + '", appending without prefix:', e);
        }
        valueToWrite = existing ? existing + '\n\n----\n\n' + content : content;
    }
    tracker.updateField(ticketKey, field, valueToWrite);
    return { field: field, operationType: operationType, length: valueToWrite.length };
}

// ── Confluence publish ───────────────────────────────────────────────────────

function sanitizeFileName(title) {
    return String(title || 'untitled').replace(/[\\/:*?"<>|]/g, '-').trim();
}

function findTicketPage(children, ticketKey) {
    if (!children || !Array.isArray(children)) return null;
    for (var i = 0; i < children.length; i++) {
        var c = children[i];
        if (c && c.title && c.title.indexOf(ticketKey) === 0) {
            return c;
        }
    }
    return null;
}

function buildPageTitle(cfg, ticketKey, summary) {
    var base = summary ? (ticketKey + ' ' + summary) : ticketKey;
    return cfg.pageTitleSuffix ? base + ' — ' + cfg.pageTitleSuffix : base;
}

function buildPageUrl(page) {
    if (!page || !page._links) return null;
    var webui = page._links.webui;
    if (!webui) return null;
    var base = page._links.base;
    if (!base) return null;
    return base + webui;
}

function resolvePageUrl(page) {
    var direct = buildPageUrl(page);
    if (direct) return direct;
    try {
        var fresh = confluence_content_by_id({ contentId: page.id });
        return buildPageUrl(fresh);
    } catch (e) {
        return null;
    }
}

/**
 * Find-or-create the ticket's page under cfg.parentPageId and publish
 * `content` (Markdown) as the page body via confluence_sync_markdown_directory,
 * so Markdown is properly converted to Confluence storage format.
 * Returns { page, url, created }.
 */
function publishPage(cfg, ticketKey, summary, content) {
    if (!cfg.space || !cfg.parentPageId) {
        throw new Error('contentOutput.space / contentOutput.parentPageId are not configured');
    }
    var pageTitle = buildPageTitle(cfg, ticketKey, summary);

    var children = confluence_get_children_by_id({ contentId: cfg.parentPageId, format: 'md' });
    var page = findTicketPage(children, ticketKey);
    var created = false;

    if (!page) {
        console.log('No existing page for ' + ticketKey + ' — creating "' + pageTitle + '"');
        page = confluence_create_page({
            title: pageTitle,
            parentId: cfg.parentPageId,
            body: '<p>Content is synced from the agent output.</p>',
    …

/**
 * Write Content Output — unified post-action for content-generating agents
 * (story_description, story_acceptance_criteria, …).
 *
 * Reads outputs/response.md and routes it according to
 * customParams.contentOutput (see js/common/contentOutput.js):
 *
 *   target: 'jira_field'  → write to the tracker field (default; replaces the
 *                           former outputType: 'field' behavior 1:1)
 *   target: 'confluence'  → publish to a Confluence page under
 *                           contentOutput.parentPageId; optionally writes a
 *                           link into the tracker field (updateTrackerField)
 *   target: 'both'        → tracker field AND Confluence page
 *
 * With Confluence targets, replies from outputs/confluence_replies.json are
 * posted back to inline comments via confluence_reply_to_inline_comment.
 *
 * After writing, follow-up behavior:
 *   - contentOutput.thenAction — path to another JS action (e.g.
 *     'assignForSolutionArchitecture.js') invoked with the same params after
 *     a successful write. Use it to keep existing assign/transition/autoStart
 *     flows unchanged.
 *   - otherwise, when contentOutput.assignForReview is not false, the ticket
 *     is assigned for review (same behavior as the former assignForReview
 *     post-action). Target review status can be overridden via
 *     contentOutput.reviewStatus (default: STATUSES.IN_REVIEW).
 *
 * The action is split into small decide/build/step helpers (gh-1037 CRAP
 * refactor). Every helper preserves the original log lines, tracker/SCM
 * call order and return shapes — the orchestration in `action` alone decides
 * sequencing and early returns.
 */

var contentOutput = require('./common/contentOutput.js');
var outputFiles = require('./common/outputFiles.js');
var jiraHelpers = require('./common/jiraHelpers.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');
var config = require('./config.js');
// Load-time require (gh-823): a deferred require would resolve against the
// pack js/ root only — hoist every require to the top of the module.
var configLoader = require('./configLoader.js');

// ---------------------------------------------------------------------------
// Parse/build helpers (pure)
// ---------------------------------------------------------------------------

/** 'ctx_wip' label from metadata.contextId, null when absent. */
function buildWipLabel(params) {
    return params.metadata && params.metadata.contextId
        ? params.metadata.contextId + '_wip'
        : null;
}

/** The target=..., field=..., confluence=... suffix of the startup log line. */
function describeTarget(cfg) {
    return 'target=' + cfg.target +
        ', field=' + (cfg.field || '(none)') +
        ', confluence=' + (cfg.space || '?') + '/' + (cfg.parentPageId || '?');
}

/** loadProjectConfig is optional — any failure leaves it null. */
function loadProjectConfigSafe(params) {
    try {
        return configLoader.loadProjectConfig(params.jobParams || params);
    } catch (e) { /* optional */ return null; }
}

function createTrackerFor(params, projectConfig) {
    return trackersModule.createTracker(projectConfig,
        (params.jobParams && params.jobParams.customParams) || params.customParams || {});
}

/** Trimmed outputs/response.md, or null (after logging) when missing/empty. */
function readResponseContent(ticketKey, workingDir) {
    var content = outputFiles.readOutputFile('response.md', {
        ticketKey: ticketKey,
        workingDir: workingDir
    });
    if (!content || !content.trim()) {
        console.error('outputs/response.md not found or empty');
        return null;
    }
    return content.trim();
}

// ---------------------------------------------------------------------------
// Step helpers — each preserves the original side effects, log lines and
// failure return shapes; they return `result` unchanged on success.
// ---------------------------------------------------------------------------

/** Step 1: Jira field (default behavior). */
function writeJiraFieldStep(result, cfg, ticketKey, content, tracker) {
    if (!contentOutput.isJiraFieldTarget(cfg)) return result;
    if (!cfg.field) {
        return { success: false, error: 'contentOutput.field is required for jira_field target' };
    }
    try {
        contentOutput.writeToTrackerField(ticketKey, cfg.field, content, cfg.operationType || 'replace', tracker);
        console.log('Updated "' + cfg.field + '" field for ' + ticketKey);
        result.field = cfg.field;
    } catch (e) {
        console.error('Failed to update field "' + cfg.field + '":', e);
        return { success: false, error: 'Field update failed: ' + e.toString() };
    }
    return result;
}

function logReplySummary(replies) {
    if (replies.posted > 0 || replies.failed > 0) {
        console.log('Replied to ' + replies.posted + ' inline comment(s)' +
            (replies.failed > 0 ? ', ' + replies.failed + ' failed' : ''));
    }
}

/** Tracker-field link line for a published Confluence page. */
function buildConfluenceLinkText(pageUrl, pageId) {
    return pageUrl
        ? 'Published to Confluence: ' + pageUrl
        : 'Published to Confluence page ' + pageId;
}

/** Tracker comment body for a published Confluence page. */
function buildConfluenceCommentText(pageUrl, pageId) {
    return 'h3. 📄 Content published to Confluence\n\n' +
        (pageUrl ? 'Page: ' + pageUrl : 'Page id: ' + pageId);
}

/** Confluence-only: write the page link into the tracker field (non-fatal). */
function writeConfluenceLinkToField(cfg, ticketKey, pageUrl, pageId, tracker) {
    if (cfg.updateTrackerField !== false && cfg.target === 'confluence') {
        try {
            contentOutput.writeToTrackerField(ticketKey, cfg.field || 'Description', buildConfluenceLinkText(pageUrl, pageId), 'replace', tracker);
        } catch (e) {
            console.warn('Failed to write Confluence link to tracker field:', e);
        }
    }
}

/** Post the "Content published" comment on the ticket (non-fatal). */
function postConfluenceLinkComment(tracker, ticketKey, pageUrl, pageId) {
    try {
        tracker.postComment(ticketKey, buildConfluenceCommentText(pageUrl, pageId));
    } catch (e) {
        console.warn('Failed to post Confluence link comment:', e);
    }
}

/** Step 2: Confluence page (replies first, then page body). */
function publishConfluenceStep(result, cfg, ticketKey, summary, content, tracker) {
    if (!contentOutput.isConfluenceTarget(cfg)) return result;
    try {
        // Post replies to inline comments BEFORE the page body is replaced —
        // while the comment anchors are still alive on the old content.
        var replies = contentOutput.publishCommentReplies(contentOutput.DEFAULT_REPLIES_FILE);
        result.replies = replies;
        logReplySummary(replies);

        var published = contentOutput.publishPage(cfg, ticketKey, summary, content);
        result.pageId = published.page && published.page.id;
        result.pageUrl = published.url;
        result.pageCreated = published.created;
        console.log('Published content to Confluence page ' + result.pageId + ' (' + (result.pageUrl || 'url unknown') + ')');

