                        var rootPrefix = '`' + rootKey + '.';
                        if (humanDoc && humanDoc.indexOf(rootMention) === -1 && humanDoc.indexOf(rootPrefix) === -1) {
                            failures.push(name + ': human doc does not describe customParams.' + rootKey + ' used by ' + base);
                        }
                    });
                }
