                var keyPrefix = '`' + k + '.';
                if (humanDoc && humanDoc.indexOf(keyMention) === -1 && humanDoc.indexOf(keyPrefix) === -1) {
                    failures.push(name + ': human doc does not describe customParams key ' + k);
                }
