            './agents/prompts/wiki_publisher_prompt.md',
            './.dmtools/skills/checklist_rules.md',
            './.dmtools/prompts/wiki_focus.md',
            './agents/instructions/common/codegraph_tools.md'
        ]);
        assert.equal(resolved.cliPromptsStrategy, 'merge');
    });
});
