   // gh-1112: preCliContentOutputSetup owns the parent-context step in its own
   // chain (and calls it with full fault isolation) — skip the built-in call
   // when the caller marks it handled, so the parent JQL is not fired twice.
   if (!params.skipParentContext) {
       try {
           fetchParentContextToInput.action(params);
