   // '../agents/wiki_publisher.json' (consuming-repo layout) or 'agents/wiki_publisher.json'
   var p = String(path || '').trim();
   var candidates = [p];
   // consuming-repo submodule layouts → this repo root
   if (p.indexOf('../agents/') === 0) candidates.push(p.substring('../'.length)); // 'agents/x' 
   else if (p.indexOf('agents/') === 0) candidates.push(p.substring('agents/'.length));
   if (p.indexOf('./') === 0) candidates.push(p.substring(2));
   for (...) try read, first hit wins
}

function loadAgentConfig(path) {
   var raw = tryReadFile(resolveAgentConfigPath(path));
   if (!raw) { warn; return null; }
   var config = JSON.parse(raw) — on parse error warn + return null;
   var parentRef = (config.parent) || (config.params && config.params.parent) || null;
   if (!parentRef || !parentRef.path) return config; // unchanged
   var parentConfig = loadAgentConfig(resolved parent path) — recursion; null → warn + strip parent + return config;
   // merge: parent is base, child overrides
   var mergedParams = deepMerge(parentConfig.params || {}, config.params || {});
   // wait — deepMerge merges nested objects and overrides scalars — good for customParams.contentOutput.
   // For merge paths (arrays): parent array entries FIRST, then child entries appended (deduped?).
   (parentRef.merge || DEFAULT_PARENT_MERGE).forEach(function(mergePath) {
       var parentVal = getByPath(parentConfig, mergePath);
       var childVal = getByPath(config, mergePath);
       if (Array.isArray(parentVal) || Array.isArray(childVal)) {
           var combined = [].concat(parentVal || [], (childVal || []).filter(function(item) {
               return (parentVal || []).indexOf(item) === -1;
           }));
           setByPath(merged, mergePath, combined);
